using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

/// <summary>
/// MCP tools that wrap the JSONPlaceholder REST API.
/// Non-static class — the SDK creates an instance per invocation and injects
/// constructor dependencies (IHttpClientFactory, ILogger) automatically.
/// </summary>
[McpServerToolType]
public class PostTools(IHttpClientFactory httpFactory, ILogger<PostTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("Get a blog post by its numeric ID.")]
    public async Task<string> GetPost(
        [Description("The post ID (1-100)")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching post {Id}", id);
        var client = httpFactory.CreateClient("api");
        var json = await client.GetStringAsync($"/posts/{id}", cancellationToken);
        return json;
    }

    [McpServerTool, Description("List posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Filter by user ID (omit for all posts)")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var client = httpFactory.CreateClient("api");
        var url = userId.HasValue ? $"/posts?userId={userId}" : "/posts";
        var json = await client.GetStringAsync(url, cancellationToken);

        // Return a summary to keep responses concise for the LLM.
        using var doc = JsonDocument.Parse(json);
        var posts = doc.RootElement.EnumerateArray()
            .Select(p => new
            {
                id = p.GetProperty("id").GetInt32(),
                title = p.GetProperty("title").GetString()
            });
        return JsonSerializer.Serialize(posts, JsonOptions);
    }

    [McpServerTool, Description("Get all comments on a specific post.")]
    public async Task<string> GetComments(
        [Description("The post ID to get comments for")] int postId,
        CancellationToken cancellationToken = default)
    {
        var client = httpFactory.CreateClient("api");
        var json = await client.GetStringAsync($"/posts/{postId}/comments", cancellationToken);
        return json;
    }
}

